(()=>{"use strict";const $=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:4});function gpaCalc(rows){const used=rows.filter(r=>!isNaN(r.g)&&!isNaN(r.c)&&r.c>0),pts=used.reduce((a,r)=>a+r.g*r.c,0),cred=used.reduce((a,r)=>a+r.c,0);return{used,pts,cred,gpa:cred>0?pts/cred:null}}function render(){const rows=[1,2,3,4].map(i=>({g:parseFloat($("g"+i).value),c:parseFloat($("c"+i).value)}));if(rows.some(row=>Number.isNaN(row.g)!==Number.isNaN(row.c))){for(const id of["result","chipCred","chipPts","tCred","tPts"])$(id).textContent="\u2014";$("gpaRows").replaceChildren(),$("note").textContent=window.CMI18n.pick("Complete both grade and credits, or leave both fields empty for an unused course.|\u6BCF\u95E8\u8BFE\u7A0B\u8BF7\u5B8C\u6574\u586B\u5199\u7EE9\u70B9\u548C\u5B66\u5206\uFF0C\u6216\u5C06\u4E24\u9879\u5747\u7559\u7A7A\u3002"),window.__summary="";return}const r=gpaCalc(rows);let rh="";if(rows.forEach((row,i)=>{!isNaN(row.g)&&!isNaN(row.c)&&row.c>0&&(rh+="<tr><td>Course "+(i+1)+"</td><td class='num'>"+fmt(row.g)+"</td><td class='num'>"+fmt(row.c)+"</td><td class='num'>"+fmt(row.g*row.c)+"</td></tr>")}),$("gpaRows").innerHTML=rh,r.gpa===null){$("result").textContent="\u2014",$("chipCred").textContent="\u2014",$("chipPts").textContent="\u2014",$("tCred").textContent="\u2014",$("tPts").textContent="\u2014",$("note").textContent="Enter at least one course with credits above zero.",window.__summary="";return}$("result").textContent=fmt(r.gpa),$("chipCred").textContent=fmt(r.cred),$("chipPts").textContent=fmt(r.pts),$("tCred").textContent=fmt(r.cred),$("tPts").textContent=fmt(r.pts),$("note").textContent=fmt(r.pts)+" grade points over "+fmt(r.cred)+" credits.",window.__summary="GPA: "+fmt(r.gpa)+" ("+fmt(r.pts)+" points over "+fmt(r.cred)+" credits)."}document.querySelectorAll("input,select").forEach(e=>e.addEventListener("input",render)),render()})();
